from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    year, month, day = (int(p) for p in start.split("-"))
    anchor = date(year, month, day)
    parts = rule.split(" ")
    kind = parts[0]
    step = int(parts[1])
    out = []

    def emit(dt):
        if dt is not None and dt >= anchor:
            out.append(dt.isoformat())
        return len(out) >= count

    def shift_month(y, m, n):
        idx = y * 12 + (m - 1) + n
        return idx // 12, idx % 12 + 1

    wd_index = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}

    if kind == "DAILY":
        cur = anchor
        for _ in range(count):
            out.append(cur.isoformat())
            cur += timedelta(days=step)
        return out

    if kind == "WEEKLY":
        wanted = sorted(wd_index[tok] for tok in parts[2].split(","))
        week0 = anchor - timedelta(days=anchor.weekday())
        w = 0
        while len(out) < count:
            monday = week0 + timedelta(days=7 * w)
            for wd in wanted:
                if emit(monday + timedelta(days=wd)):
                    return out
            w += step
        return out

    if kind == "MONTHLY" and len(parts) == 3:
        dom = int(parts[2])
        i = 0
        while len(out) < count:
            yy, mm = shift_month(anchor.year, anchor.month, i)
            last = calendar.monthrange(yy, mm)[1]
            if dom == -1:
                cand = date(yy, mm, last)
            elif 1 <= dom <= last:
                cand = date(yy, mm, dom)
            else:
                cand = None
            if emit(cand):
                return out
            i += step
        return out

    if kind == "MONTHLY":
        nth = int(parts[2])
        wd = wd_index[parts[3]]
        i = 0
        while len(out) < count:
            yy, mm = shift_month(anchor.year, anchor.month, i)
            if nth == -1:
                last_n = calendar.monthrange(yy, mm)[1]
                last_dt = date(yy, mm, last_n)
                cand = last_dt - timedelta(days=(last_dt.weekday() - wd) % 7)
            else:
                first = date(yy, mm, 1)
                day_num = 1 + (wd - first.weekday()) % 7 + (nth - 1) * 7
                last_n = calendar.monthrange(yy, mm)[1]
                cand = date(yy, mm, day_num) if day_num <= last_n else None
            if emit(cand):
                return out
            i += step
        return out

    mm_s, dd_s = parts[2].split("-")
    mm, dd = int(mm_s), int(dd_s)
    i = 0
    while len(out) < count:
        yy = anchor.year + i
        try:
            cand = date(yy, mm, dd)
        except ValueError:
            cand = None
        if emit(cand):
            return out
        i += step
    return out
